import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { isIP } from "node:net";
import path from "node:path";
import { beforeAll, describe, expect, it } from "vitest";
import { extract, type Extracted, matchesSpec, specById } from "./index.ts";

/**
 * Golden set for detection (P1-020): fixtures/detect/golden.jsonl, 5,000 snippets generated by
 * packages/core/scripts/gen-golden.mjs with its own checksum implementations. This file is the second review: every
 * label must also pass the core validators, every near miss must fail them, and the extractor is scored on it.
 */
interface Entity {
  start: number;
  end: number;
  value: string;
  type: string;
  accept: string[];
  family: string;
}
interface Near {
  start: number;
  end: number;
  value: string;
  reject: string[];
  family: string;
}
interface Row {
  id: string;
  lang: "ar" | "en";
  text: string;
  entities: Entity[];
  negatives: Near[];
}

const root = path.resolve(import.meta.dirname, "..", "..", "..", "..");
const dir = path.join(root, "fixtures", "detect");
const raw = readFileSync(path.join(dir, "golden.jsonl"), "utf8");
const rows = raw
  .trim()
  .split("\n")
  .map((l) => JSON.parse(l) as Row);
const manifest = JSON.parse(readFileSync(path.join(dir, "manifest.json"), "utf8")) as { snippets: number; sha256: string };
const deterministic = (e: Entity) => Boolean(specById(e.type)?.validator);
const entities = rows.flatMap((r) => r.entities);
const nears = rows.flatMap((r) => r.negatives);

// An extraction is right when its best type is acceptable, or ties with an acceptable type (identical evidence, D-007).
const right = (g: Extracted | undefined, e: Entity): boolean =>
  g !== undefined && (e.accept.includes(g.best.type) || g.candidates.some((c) => e.accept.includes(c.type) && c.score === g.best.score));

describe("golden set: the fixture itself", () => {
  it("has 5,000 snippets, unique ids, a matching manifest hash, and correct spans", () => {
    expect(rows).toHaveLength(5000);
    expect(manifest.snippets).toBe(5000);
    expect(new Set(rows.map((r) => r.id)).size).toBe(5000);
    expect(createHash("sha256").update(raw).digest("hex")).toBe(manifest.sha256);
    for (const r of rows) for (const e of [...r.entities, ...r.negatives]) expect(r.text.slice(e.start, e.end), r.id).toBe(e.value);
    expect(rows.filter((r) => r.lang === "ar").length).toBeGreaterThan(2000);
  });

  it("is reproducible from the seeded generator", () => {
    const r = spawnSync(process.execPath, [path.join(root, "packages/core/scripts/gen-golden.mjs"), "--check"], { encoding: "utf8" });
    expect(r.stdout.trim()).toBe("golden: reproducible");
  }, 60_000);

  it("contains no real persons' data: test BINs, fiction phone ranges, documentation IP ranges", () => {
    for (const e of entities) {
      if (/card/.test(e.family)) expect(["400000", "424242", "555555", "510510", "378282", "371449"]).toContain(e.value.slice(0, 6));
      if (e.family === "phone_uk") expect(e.value).toMatch(/^\+447700900\d{3}$/);
      if (e.family === "phone_us") expect(e.value).toMatch(/-555-01\d{2}$/);
      if (e.family === "ipv4_public") expect(e.value).toMatch(/^(192\.0\.2|198\.51\.100|203\.0\.113)\./);
      if (e.family === "ipv6") expect(e.value.startsWith("2001:db8:")).toBe(true);
    }
  });
});

describe("golden set: second review against independent implementations", () => {
  it("every label is accepted by its declared type in @ir/core; deterministic labels pass the validator", () => {
    const bad = entities.filter((e) => {
      const spec = specById(e.type);
      const m = spec ? matchesSpec(spec, e.value) : { pattern: false, valid: false };
      return !m.pattern || m.valid === false || (deterministic(e) && m.valid !== true);
    });
    expect(bad.map((e) => `${e.type} ${e.value}`)).toEqual([]);
  });

  it("every near miss is rejected by each type it imitates", () => {
    const bad = nears.filter((n) =>
      n.reject.some((t) => {
        const spec = specById(t);
        const m = spec ? matchesSpec(spec, n.value) : { pattern: false, valid: null };
        return m.pattern && m.valid !== false;
      }),
    );
    expect(bad.map((n) => `${n.family} ${n.value}`)).toEqual([]);
  });

  it("IP labels agree with node:net", () => {
    for (const e of entities)
      if (/^ip/.test(e.type) || ["multicast_ip", "vpn_ip"].includes(e.type)) expect(isIP(e.value), e.value).toBe(e.type === "ipv6" ? 6 : 4);
    for (const n of nears) if (n.family === "ipv4") expect(isIP(n.value)).toBe(0);
  });
});

describe("golden set: extractor scores (UC-02, D-005)", () => {
  let results: Map<string, Extracted[]>;
  beforeAll(() => {
    results = new Map(rows.map((r) => [r.id, extract(r.text)]));
  }, 120_000);
  const at = (id: string, s: number, e: number) => results.get(id)?.find((g) => g.start === s && g.end === e);

  it("deterministic types: precision and recall at least 99%", () => {
    let tp = 0,
      fp = 0,
      found = 0,
      total = 0;
    for (const r of rows) {
      for (const e of r.entities.filter(deterministic)) {
        total++;
        if (right(at(r.id, e.start, e.end), e)) found++;
      }
      for (const g of results.get(r.id) ?? []) {
        if (!g.best.validated) continue;
        const label = r.entities.find((e) => e.start === g.start && e.end === g.end);
        if (label && right(g, label)) tp++;
        else fp++;
      }
    }
    expect(tp / (tp + fp)).toBeGreaterThanOrEqual(0.99);
    expect(found / total).toBeGreaterThanOrEqual(0.99);
  });

  it("no near miss is reported as a validated identifier of the type it imitates", () => {
    const bad = rows.flatMap((r) =>
      r.negatives.filter((n) => {
        const g = at(r.id, n.start, n.end);
        return g?.best.validated && n.reject.includes(g.best.type);
      }),
    );
    expect(bad.map((n) => n.value)).toEqual([]);
  });

  it("other types (email, hashes, MAC, URL, phones): recall at least 95%; ordinary words are not reported", () => {
    const other = rows.flatMap((r) => r.entities.filter((e) => !deterministic(e)).map((e) => ({ r, e })));
    const found = other.filter(({ r, e }) => right(at(r.id, e.start, e.end), e)).length;
    expect(found / other.length).toBeGreaterThanOrEqual(0.95);
    const spurious = rows.flatMap((r) =>
      (results.get(r.id) ?? []).filter(
        (g) => !r.entities.some((e) => e.start === g.start) && !r.negatives.some((n) => n.start === g.start),
      ),
    );
    expect(spurious.length).toBeLessThanOrEqual(10);
  });
});

describe("extract: robustness", () => {
  it("trims punctuation in linear time and keeps spans exact", () => {
    const t0 = Date.now();
    expect(extract(`(${"!".repeat(50_000)}`)).toEqual([]);
    expect(Date.now() - t0).toBeLessThan(2000);
    const text = "«192.0.2.7»، ثم (DE89370400440532013000).";
    const got = extract(text);
    expect(got.map((g) => text.slice(g.start, g.end))).toEqual(["192.0.2.7", "DE89370400440532013000"]);
  });
});
